define([], function() { const placeDashboardTermine = function() { const pending = document.getElementById('local-termine-dashboard-pending'); if (!pending) { return; } let section = document.getElementById('dashboard-upcoming-events'); if (!section || section.closest('#local-termine-dashboard-pending')) { section = pending.querySelector('#dashboard-upcoming-events'); } if (!section) { return; } const main = document.querySelector('#region-main'); if (!main) { return; } pending.removeAttribute('id'); pending.classList.remove('local-termine-dashboard-pending'); main.insertBefore(pending, main.firstChild); }; const init = function() { if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', placeDashboardTermine); } else { placeDashboardTermine(); } }; return { init: init, }; });